import sys
from collections import defaultdict
sys.setrecursionlimit(300000)

class Solution:
    def interactionCost(self, n, edges, group):
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        cnt = defaultdict(int)
        for g in group:
            cnt[g] += 1
        ans = 0
        def dfs(u, p):
            nonlocal ans
            cur = {group[u]: 1}
            for v in adj[u]:
                if v == p:
                    continue
                sub = dfs(v, u)
                if len(sub) > len(cur):
                    cur, sub = sub, cur
                for g, a in sub.items():
                    ans += a * (cnt[g] - a)
                    cur[g] = cur.get(g, 0) + a
            return cur
        dfs(0, -1)
        return ans

