class Solution {
    private List<List<Integer>> adj;
    private int[] group;
    private long[] cnt;
    private long ans;

    public long interactionCost(int n, int[][] edges, int[] group) {
        this.group = group;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        cnt = new long[n + 1];
        for (int g : group) cnt[g]++;
        ans = 0;
        dfs(0, -1);
        return ans;
    }

    private HashMap<Integer, Integer> dfs(int u, int p) {
        HashMap<Integer, Integer> cur = new HashMap<>();
        cur.put(group[u], 1);
        for (int v : adj.get(u)) {
            if (v == p) continue;
            HashMap<Integer, Integer> sub = dfs(v, u);
            if (sub.size() > cur.size()) { HashMap<Integer, Integer> t = cur; cur = sub; sub = t; }
            for (Map.Entry<Integer, Integer> en : sub.entrySet()) {
                int g = en.getKey(), a = en.getValue();
                ans += (long) a * (cnt[g] - a);
                cur.merge(g, a, Integer::sum);
            }
        }
        return cur;
    }
}

