from collections import deque, defaultdict

class Solution:
    def interactionCost(self, n, edges, group):
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        buckets = defaultdict(list)
        for i, g in enumerate(group):
            buckets[g].append(i)
        ans = 0
        for g, nodes in buckets.items():
            for src in nodes:
                dist = [-1] * n
                dist[src] = 0
                q = deque([src])
                while q:
                    u = q.popleft()
                    for v in adj[u]:
                        if dist[v] == -1:
                            dist[v] = dist[u] + 1
                            q.append(v)
                for w in nodes:
                    if w > src:
                        ans += dist[w]
        return ans

