class Solution {
    public long interactionCost(int n, int[][] edges, int[] group) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        Map<Integer, List<Integer>> buckets = new HashMap<>();
        for (int i = 0; i < n; i++) buckets.computeIfAbsent(group[i], k -> new ArrayList<>()).add(i);
        long ans = 0;
        for (List<Integer> nodes : buckets.values()) {
            for (int src : nodes) {
                int[] dist = new int[n];
                Arrays.fill(dist, -1);
                dist[src] = 0;
                Queue<Integer> q = new LinkedList<>(); q.add(src);
                while (!q.isEmpty()) {
                    int u = q.poll();
                    for (int v : adj.get(u)) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.add(v); }
                }
                for (int w : nodes) if (w > src) ans += dist[w];
            }
        }
        return ans;
    }
}

